def get_api_key_hash(key: str) -> str:
    return sha256(key.encode()).hexdigest()

def get_api_key() -> str:
    return settings.api_keys[0]

app = FastAPI()

@app.get("/me")
def me(api_key: str = Depends(get_api_key)):
    if api_key != get_api_key_hash(settings.api_key_secret):
        raise HTTPException(status_code=401, detail="Invalid API key")
    return {"api_key": api_key}

@app.post("/keys")
def add_key(key: str):
    if key in settings.api_keys:
        raise HTTPException(status_code=409, detail="Key already exists")
    settings.api_keys.append(key)
    return {"added": key}
